using Archy.Features.Decisions.ArchitectureDecisions; using Archy.SharedKernel.Primitives;
namespace Archy.Features.Placement.ApplyPlacementDecisionFeedback;
public static class PlacementReviewDecisionFactory { public const string DecisionType="placement_review"; public static ArchitectureDecisionFact Create(PlacementReviewDecision decision){ArgumentNullException.ThrowIfNull(decision);if(string.IsNullOrWhiteSpace(decision.PlacementFindingId)||string.IsNullOrWhiteSpace(decision.ActorKind)||string.IsNullOrWhiteSpace(decision.ActorId)||!Enum.IsDefined(decision.Resolution)||decision.GraphRevision is<1)throw new ArgumentException("Placement reviews require an exact finding, actor, resolution, and valid optional revision.",nameof(decision));return new(DecisionType,decision.Resolution,decision.Note,decision.ActorKind,decision.ActorId,decision.SessionId,decision.GraphRevision,[new ArchitectureTarget(ArchitectureTargetKind.PlacementFinding,decision.PlacementFindingId)]);}}
